// Writes a cover letter for each of today's picks.
//
// The letters are assembled, not generated by a model — there is no paid API in
// this project. What makes them worth sending is that the evidence is *selected*
// per posting: a job that talks about MQTT gets the device-integration paragraph,
// one that talks about ERP gets the multi-tenant one. A letter that names the
// company, the role, and the two things about your background that actually bear
// on it beats a generic one, and this is the part that is mechanical.
//
// Read every letter before you send it. They are a first draft with the right
// facts in the right order, not a finished document.

import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import profile from './profile.js';
import { contains } from './match.js';
import { ROOT, isMain } from './paths.js';

const DATA = path.join(ROOT, 'data');

// Each entry: when the posting mentions any `when` term, the paragraph is
// eligible. Ordered by how strong the evidence is.
const EVIDENCE = [
  {
    when: ['angular', 'typescript', 'rxjs', 'frontend', 'front-end', 'front end'],
    text: 'On the front end I build the Angular side of a multi-tenant ERP — a reusable '
        + 'component architecture on Angular Material and Tailwind, with full multilingual '
        + 'and RTL support across every module.',
  },
  {
    when: ['.net', 'asp.net', 'c#', 'dotnet', 'backend', 'back-end', 'api', 'rest'],
    text: 'On the back end I design and maintain the ASP.NET Core REST APIs behind the '
        + 'HR, Finance, Procurement, Asset Management and CRM modules, along with the '
        + 'SQL Server schema and data-access layers built on EF Core and Dapper.',
  },
  {
    when: ['erp', 'multi-tenant', 'multitenant', 'saas', 'enterprise'],
    text: 'My day job is a large-scale multi-tenant ERP serving eight business domains, '
        + 'so I am used to the constraints that come with shared schemas, tenant isolation '
        + 'and features that cannot break the other seven modules when they ship.',
  },
  {
    when: ['mqtt', 'iot', 'device', 'real-time', 'realtime', 'websocket', 'hardware', 'embedded'],
    text: 'I also own our hardware integration: biometric and access-control devices '
        + 'talking to the ERP over MQTT, keeping device state and application state in '
        + 'sync in real time.',
  },
  {
    when: ['azure', 'cloud', 'devops', 'infrastructure', 'kubernetes', 'docker'],
    text: 'I hold the Microsoft Azure AZ-104 certification and am comfortable owning the '
        + 'deployment side of what I build rather than handing it over.',
  },
  {
    when: ['sql', 'database', 'postgres', 'query', 'performance'],
    text: 'A good share of my work is database-side — schema design, business logic and '
        + 'query performance on SQL Server under real production load.',
  },
];

function pickEvidence(job, max = 3) {
  const blob = `${job.title} ${job.description} ${(job.tags || []).join(' ')}`.toLowerCase();
  const hits = EVIDENCE.filter((e) => e.when.some((w) => contains(blob, w)));
  // A posting with no description (LinkedIn alerts) still deserves a letter, so
  // fall back to the two strongest paragraphs rather than producing nothing.
  const chosen = hits.length ? hits : [EVIDENCE[1], EVIDENCE[0]];
  return chosen.slice(0, max).map((e) => e.text);
}

function closing(job) {
  const flags = job.score?.flags || [];
  // He is Bahraini, so a GCC national: in Bahrain that also makes him the hire
  // Bahrainisation targets, and elsewhere in the GCC it means no sponsorship.
  // Both are worth saying outright — a Gulf recruiter screens on it first.
  if (flags.includes('no-visa-needed') && job.score?.region === 'Bahrain') {
    return 'I am a Bahraini national based in Manama, so there is no visa or work-permit '
         + 'process involved and I count towards your Bahrainisation targets.';
  }
  if (flags.includes('no-visa-needed')) {
    return 'I am a Bahraini national, and as a GCC citizen I can work in '
         + `${job.location || 'the Gulf'} without employer sponsorship or a work visa.`;
  }
  if (flags.includes('sponsors')) {
    return `I am currently in Bahrain and would be relocating for this role — I saw that `
         + `${job.company} supports sponsorship, which is why I am applying.`;
  }
  if (flags.includes('needs-sponsorship')) {
    return 'I am currently based in Bahrain and would need visa sponsorship to relocate. '
         + 'If that is possible for this role I would be glad to talk; if not, I would '
         + 'rather know early than take up your time.';
  }
  return 'I am based in Manama, Bahrain and work well with distributed teams across '
       + 'European and Gulf time zones.';
}

export function writeLetter(job) {
  const role = job.title;
  const company = job.company || 'your team';
  const evidence = pickEvidence(job);

  const opener = `I am applying for the ${role} position at ${company}. I am a full-stack `
    + `engineer with ${profile.yearsExperience} years building enterprise software in `
    + `Angular and ASP.NET Core, and the work you describe lines up closely with what I do `
    + `every day.`;

  return [
    `Dear ${company} hiring team,`,
    '',
    opener,
    '',
    ...evidence.flatMap((e) => [e, '']),
    closing(job),
    '',
    'My CV is attached. Thank you for your time — I would welcome the chance to talk.',
    '',
    'Kind regards,',
    profile.name,
    `${profile.email} · ${profile.phone}`,
    profile.linkedin,
  ].join('\n');
}

async function main() {
  const state = JSON.parse(await readFile(path.join(DATA, 'jobs.json'), 'utf8'));
  let letters = {};
  try { letters = JSON.parse(await readFile(path.join(DATA, 'letters.json'), 'utf8')); } catch {}

  const targets = [...(state.picks || []), ...(state.queue || []).slice(0, 20)];
  let written = 0;
  for (const job of targets) {
    if (letters[job.id]) continue;
    letters[job.id] = {
      title: job.title,
      company: job.company,
      writtenAt: new Date().toISOString(),
      text: writeLetter(job),
    };
    written++;
  }

  await writeFile(path.join(DATA, 'letters.json'), JSON.stringify(letters, null, 2));
  console.log(`  ${written} new letter(s), ${Object.keys(letters).length} on file`);
}

if (isMain(import.meta.url)) {
  main().catch((e) => { console.error('letters failed:', e.message); process.exit(1); });
}
